-- Source: 019_muscle_focus.sql
-- Apply after 014, 016 and 017. Atomic, owner-scoped focus blocks; no live data is rewritten on migration.
CREATE OR REPLACE FUNCTION public.apply_fitsync_focus_block(p_user_id uuid,p_plan_id uuid,p_request_id uuid,p_request_data jsonb,p_config jsonb,p_days jsonb)
RETURNS uuid LANGUAGE plpgsql SET search_path='' AS $$
DECLARE prior public.coaching_commands%ROWTYPE; plan public.coaching_plans%ROWTYPE;
  item jsonb; day public.coaching_days%ROWTYPE; source jsonb; old_focus public.companion_records%ROWTYPE;
BEGIN
  PERFORM 1 FROM public.app_users WHERE id=p_user_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Account not found.' USING ERRCODE='P0002'; END IF;
  SELECT * INTO prior FROM public.coaching_commands WHERE user_id=p_user_id AND request_id=p_request_id;
  IF FOUND THEN
    IF prior.action<>'focus' OR prior.request_data<>p_request_data THEN RAISE EXCEPTION 'This request key was used for another change.' USING ERRCODE='40001'; END IF;
    RETURN prior.result_id;
  END IF;
  SELECT * INTO plan FROM public.coaching_plans WHERE id=p_plan_id AND user_id=p_user_id AND status='active' FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Current plan not found.' USING ERRCODE='P0002'; END IF;
  IF jsonb_typeof(p_days)<>'array' OR jsonb_array_length(p_days) NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'Preview a complete focus change.' USING ERRCODE='22023'; END IF;
  IF (p_config->>'weeks')::integer NOT IN (4,8) OR (p_config->>'additionalSetsPerWeek')::integer NOT BETWEEN 1 AND 2 OR (p_config->>'startsOn')::date < (now() AT TIME ZONE plan.timezone)::date THEN RAISE EXCEPTION 'Invalid focus window.' USING ERRCODE='22023'; END IF;
  IF (SELECT count(*) FROM public.coaching_days WHERE plan_id=plan.id)<>jsonb_array_length(p_request_data->'expectedRevisions') OR EXISTS(
    SELECT 1 FROM public.coaching_days d WHERE d.plan_id=plan.id AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p_request_data->'expectedRevisions') r WHERE (r->>'id')::uuid=d.id AND (r->>'revision')::integer=d.revision)
  ) THEN RAISE EXCEPTION 'Your plan changed. Preview the focus block again.' USING ERRCODE='40001'; END IF;
  SELECT * INTO old_focus FROM public.companion_records WHERE user_id=p_user_id AND id='focus_active' FOR UPDATE;
  IF FOUND AND NOT old_focus.deleted AND (old_focus.data->>'startsOn')::date+(old_focus.data->>'weeks')::integer*7-1 >= (p_config->>'startsOn')::date THEN RAISE EXCEPTION 'An existing focus window overlaps this block. Review or end it first.' USING ERRCODE='40001'; END IF;
  FOR item IN SELECT value FROM jsonb_array_elements(p_days) LOOP
    SELECT * INTO day FROM public.coaching_days WHERE id=(item->>'id')::uuid AND plan_id=plan.id FOR UPDATE;
    IF NOT FOUND OR day.revision<>(item->>'expectedRevision')::integer THEN RAISE EXCEPTION 'A session changed. Preview again.' USING ERRCODE='40001'; END IF;
    IF day.scheduled_date NOT BETWEEN (p_config->>'startsOn')::date AND (p_config->>'startsOn')::date+(p_config->>'weeks')::integer*7-1 THEN RAISE EXCEPTION 'A session is outside the focus window.' USING ERRCODE='22023'; END IF;
    IF EXISTS(SELECT 1 FROM public.coaching_workouts c JOIN public.workout_sessions w ON w.id=c.workout_id WHERE c.day_id=day.id AND w.status IN ('active','completed')) THEN RAISE EXCEPTION 'An active or completed workout cannot change.' USING ERRCODE='40001'; END IF;
    IF jsonb_typeof(item->'prescription'->'exercises')<>'array' OR jsonb_array_length(item->'prescription'->'exercises') NOT BETWEEN 2 AND 12 OR (item->'prescription'->>'minutes')::integer NOT BETWEEN 15 AND 90 THEN RAISE EXCEPTION 'Invalid focus prescription.' USING ERRCODE='22023'; END IF;
    FOR source IN SELECT value FROM jsonb_array_elements(item->'prescription'->'exercises') LOOP
      IF NOT EXISTS(SELECT 1 FROM public.exercises WHERE id=(source->>'exerciseId')::uuid AND status='published' AND owner_user_id IS NULL) OR (source->>'sets')::integer NOT BETWEEN 1 AND 5 THEN RAISE EXCEPTION 'An exercise changed. Refresh the preview.' USING ERRCODE='40001'; END IF;
    END LOOP;
    UPDATE public.coaching_days SET prescription=item->'prescription',revision=revision+1 WHERE id=day.id;
  END LOOP;
  INSERT INTO public.companion_records(user_id,id,kind,data,revision) VALUES(p_user_id,'focus_active','specialisation',p_config,1)
  ON CONFLICT(user_id,id) DO UPDATE SET kind='specialisation',data=EXCLUDED.data,deleted=false,date=NULL,revision=companion_records.revision+1,updated_at=now();
  INSERT INTO public.coaching_commands(user_id,request_id,action,request_data,result_id) VALUES(p_user_id,p_request_id,'focus',p_request_data,plan.id);
  RETURN plan.id;
END $$;
REVOKE ALL ON FUNCTION public.apply_fitsync_focus_block(uuid,uuid,uuid,jsonb,jsonb,jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.apply_fitsync_focus_block(uuid,uuid,uuid,jsonb,jsonb,jsonb) TO service_role;

-- Source: 020_routine_editing.sql
-- Personal routine editing. Apply after 008, 014, 016 and 018, before deploying the API.
ALTER TABLE public.workout_templates ADD COLUMN IF NOT EXISTS revision integer NOT NULL DEFAULT 0 CHECK(revision>=0);
CREATE OR REPLACE FUNCTION public.bump_fitsync_template_revision() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$
BEGIN
  NEW.revision := OLD.revision+1;
  NEW.updated_at := clock_timestamp();
  RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION public.bump_fitsync_template_revision() FROM PUBLIC,anon,authenticated;
DROP TRIGGER IF EXISTS fitsync_template_revision ON public.workout_templates;
CREATE TRIGGER fitsync_template_revision BEFORE UPDATE ON public.workout_templates
FOR EACH ROW EXECUTE FUNCTION public.bump_fitsync_template_revision();

CREATE OR REPLACE FUNCTION public.edit_fitsync_workout_template(
  p_user_id uuid,p_template_id uuid,p_expected_revision integer,p_data jsonb
) RETURNS uuid LANGUAGE plpgsql SET search_path=public AS $$
DECLARE saved public.workout_templates; item jsonb; dose jsonb; item_position integer:=0; dose_position integer;
  exercise_row public.exercises; inserted_exercise uuid; existing_exercises uuid[];
BEGIN
  SELECT * INTO saved FROM public.workout_templates WHERE id=p_template_id AND user_id=p_user_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Routine not found.' USING ERRCODE='P0002'; END IF;
  IF saved.revision IS DISTINCT FROM p_expected_revision THEN RAISE EXCEPTION 'This routine changed on another device. Reload the saved routine before applying your edits.' USING ERRCODE='40001'; END IF;
  IF EXISTS(SELECT 1 FROM public.user_saved_routines WHERE template_id=p_template_id)
    OR EXISTS(SELECT 1 FROM public.user_saved_program_routines WHERE template_id=p_template_id)
    OR EXISTS(SELECT 1 FROM public.coaching_days WHERE template_id=p_template_id)
    OR EXISTS(SELECT 1 FROM public.program_workout_slots WHERE template_id=p_template_id) THEN
    RAISE EXCEPTION 'Only routines you created can be edited. Save a personal copy instead.' USING ERRCODE='42501';
  END IF;
  IF jsonb_typeof(p_data) IS DISTINCT FROM 'object' OR length(btrim(coalesce(p_data->>'name',''))) NOT BETWEEN 1 AND 100
    OR length(coalesce(p_data->>'description',''))>2000 OR jsonb_typeof(p_data->'exercises') IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION 'Invalid routine input.' USING ERRCODE='22023';
  END IF;
  IF jsonb_array_length(p_data->'exercises') NOT BETWEEN 1 AND 50 THEN RAISE EXCEPTION 'Choose 1 to 50 exercises.' USING ERRCODE='22023'; END IF;
  SELECT coalesce(array_agg(exercise_id),ARRAY[]::uuid[]) INTO existing_exercises FROM public.workout_template_exercises WHERE template_id=p_template_id;
  -- Validate all selected catalog rows before replacing anything. Keep rows stable for this transaction.
  FOR item IN SELECT value FROM jsonb_array_elements(p_data->'exercises') LOOP
    SELECT * INTO exercise_row FROM public.exercises WHERE id=(item->>'exerciseId')::uuid FOR SHARE;
    IF NOT FOUND OR NOT coalesce((
      ((exercise_row.owner_user_id IS NULL OR exercise_row.owner_user_id=p_user_id) AND exercise_row.status='published')
      OR (exercise_row.owner_user_id=p_user_id AND exercise_row.status='archived' AND exercise_row.id=ANY(existing_exercises))
    ),false) THEN RAISE EXCEPTION 'An exercise is unavailable to your account. Choose an available exercise.' USING ERRCODE='22023'; END IF;
    IF jsonb_typeof(item->'sets') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'Add sets for every exercise.' USING ERRCODE='22023'; END IF;
    IF jsonb_array_length(item->'sets') NOT BETWEEN 1 AND 30 OR length(coalesce(item->>'notes',''))>1000 THEN RAISE EXCEPTION 'Invalid exercise targets.' USING ERRCODE='22023'; END IF;
  END LOOP;
  UPDATE public.workout_templates SET name=btrim(p_data->>'name'),description=coalesce(p_data->>'description','') WHERE id=p_template_id;
  DELETE FROM public.workout_template_exercises WHERE template_id=p_template_id;
  FOR item IN SELECT value FROM jsonb_array_elements(p_data->'exercises') LOOP
    INSERT INTO public.workout_template_exercises(template_id,exercise_id,position,notes,rest_seconds,superset_group)
      VALUES(p_template_id,(item->>'exerciseId')::uuid,item_position,coalesce(item->>'notes',''),coalesce((item->>'restSeconds')::integer,90),nullif(item->>'supersetGroup','')) RETURNING id INTO inserted_exercise;
    dose_position:=0;
    FOR dose IN SELECT value FROM jsonb_array_elements(item->'sets') LOOP
      INSERT INTO public.workout_template_sets(template_exercise_id,position,set_type,target_reps,target_weight,target_duration_seconds,rest_seconds,tempo)
        VALUES(inserted_exercise,dose_position,coalesce(dose->>'setType','normal'),(dose->>'targetReps')::integer,(dose->>'targetWeight')::numeric,(dose->>'targetDurationSeconds')::integer,(dose->>'restSeconds')::integer,nullif(dose->>'tempo',''));
      dose_position:=dose_position+1;
    END LOOP;
    item_position:=item_position+1;
  END LOOP;
  RETURN p_template_id;
END $$;
REVOKE ALL ON FUNCTION public.edit_fitsync_workout_template(uuid,uuid,integer,jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.edit_fitsync_workout_template(uuid,uuid,integer,jsonb) TO service_role;

-- Explicit service access for the append-only journal (standalone 012 relies on defaults).
GRANT ALL ON public.progress_events TO service_role;
NOTIFY pgrst, 'reload schema';
COMMIT;

-- Schema-only verification; this reads no personal records.
SELECT c.relname AS table_name, c.relrowsecurity AS row_security_enabled
FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
WHERE n.nspname='public' AND c.relname IN (
  'progress_events', 'billing_entitlements', 'billing_webhook_events',
  'coaching_plans', 'coaching_days', 'coaching_workouts', 'coaching_commands',
  'wellness_preferences', 'wellness_meal_plans', 'wellness_commitments', 'accountability_partners',
  'companion_records', 'companion_photos', 'companion_shares'
) ORDER BY c.relname;
